import unittest
from candidate import smallest_change

class TestSmallestChange(unittest.TestCase):
    def test_smallest_change_palindromic_array(self):
        self.assertEqual(smallest_change([1, 2, 3, 2, 1]), 0)

    def test_smallest_change_non_palindromic_array(self):
        self.assertEqual(smallest_change([1, 2, 3, 5, 4, 7, 9, 6]), 4)

    def test_smallest_change_array_with_one_element(self):
        self.assertEqual(smallest_change([1]), 0)

    def test_smallest_change_array_with_two_elements(self):
        self.assertEqual(smallest_change([1, 2]), 1)

    def test_smallest_change_array_with_three_elements(self):
        self.assertEqual(smallest_change([1, 2, 3]), 2)

    def test_smallest_change_array_with_four_elements(self):
        self.assertEqual(smallest_change([1, 2, 3, 4]), 2)

    def test_smallest_change_empty_array(self):
        self.assertEqual(smallest_change([]), 0)

    def test_smallest_change_array_with_None(self):
        with self.assertRaises(TypeError):
            smallest_change([1, 2, None, 4])

    def test_smallest_change_array_with_non_integer_elements(self):
        with self.assertRaises(TypeError):
            smallest_change([1, 2, 'a', 4])

    def test_smallest_change_input_is_not_a_list(self):
        with self.assertRaises(TypeError):
            smallest_change('1234')

    def test_smallest_change_input_is_None(self):
        with self.assertRaises(TypeError):
            smallest_change(None)

if __name__ == '__main__':
    unittest.main()
